class User:
    def __init__(self, email):
        self._email = email
    @property
    def email(self):
        return self._email
    @email.setter
    def email(self, value):
        if '@' not in value:
            raise ValueError('Invalid email')
        self._email = value
print(User('dev@kakade.dev').email)

